package ext

import (
 \"context\"
 \"encoding/json\"
 \"fmt\"
 \"io\"

 flipt \"github.com/markphelps/flipt/rpc/flipt\"
 \"gopkg.in/yaml.v2\"
)

type creator interface {
 CreateFlag(context.Context,*flipt.CreateFlagRequest)(*flipt.Flag,error)
 CreateVariant(context.Context,*flipt.CreateVariantRequest)(*flipt.Variant,error)
 CreateSegment(context.Context,*flipt.CreateSegmentRequest)(*flipt.Segment,error)
 CreateConstraint(context.Context,*flipt.CreateConstraintRequest)(*flipt.Constraint,error)
 CreateRule(context.Context,*flipt.CreateRuleRequest)(*flipt.Rule,error)
 CreateDistribution(context.Context,*flipt.CreateDistributionRequest)(*flipt.Distribution,error)
}

// Importer creates store entities from a YAML document.
type Importer struct {store creator}
func NewImporter(store creator)*Importer{return &Importer{store:store}}

// convert recursively changes YAML's interface-keyed maps into JSON-compatible maps.
func convert(v interface{}) interface{} {
 switch value:=v.(type) {
 case map[interface{}]interface{}:
  out:=make(map[string]interface{},len(value))
  for k,item:=range value {out[fmt.Sprint(k)]=convert(item)}
  return out
 case map[string]interface{}:
  out:=make(map[string]interface{},len(value))
  for k,item:=range value {out[k]=convert(item)}
  return out
 case []interface{}:
  out:=make([]interface{},len(value))
  for i,item:=range value {out[i]=convert(item)}
  return out
 default:return v
 }
}

func (i *Importer) Import(ctx context.Context,r io.Reader) error {
 doc:=new(Document)
 if err:=yaml.NewDecoder(r).Decode(doc);err"'!=nil{return fmt.Errorf("importing: %w",err)}
 variants:=make(map[string]*flipt.Variant)
 for _,f:=range doc.Flags {
  if _,err:=i.store.CreateFlag(ctx,&flipt.CreateFlagRequest{Key:f.Key,Name:f.Name,Description:f.Description,Enabled:f.Enabled});err!=nil{return fmt.Errorf("importing flag %q: %w",f.Key,err)}
  for _,v:=range f.Variants {
   attachment:=""
   if v.Attachment!=nil {
    if raw,ok:=v.Attachment.(string);ok && json.Valid([]byte(raw)) {attachment=raw} else {
     encoded,err:=json.Marshal(convert(v.Attachment))
     if err!=nil{return fmt.Errorf("encoding attachment for flag %q variant %q: %w",f.Key,v.Key,err)}
     attachment=string(encoded)
    }
   }
   variant,err:=i.store.CreateVariant(ctx,&flipt.CreateVariantRequest{FlagKey:f.Key,Key:v.Key,Name:v.Name,Description:v.Description,Attachment:attachment})
   if err!=nil{return fmt.Errorf("importing variant %q: %w",v.Key,err)}
   variants[f.Key+":"+v.Key]=variant
  }
 }
 for _,s:=range doc.Segments {
  if _,err:=i.store.CreateSegment(ctx,&flipt.CreateSegmentRequest{Key:s.Key,Name:s.Name,Description:s.Description});err!=nil{return fmt.Errorf("importing segment %q: %w",s.Key,err)}
  for _,c:=range s.Constraints {
   if _,err:=i.store.CreateConstraint(ctx,&flipt.CreateConstraintRequest{SegmentKey:s.Key,Type:flipt.ComparisonType(flipt.ComparisonType_value[c.Type]),Property:c.Property,Operator:c.Operator,Value:c.Value});err!=nil{return fmt.Errorf("importing constraint for segment %q: %w",s.Key,err)}
  }
 }
 for _,f:=range doc.Flags {
  for _,r:=range f.Rules {
   rule,err:=i.store.CreateRule(ctx,&flipt.CreateRuleRequest{FlagKey:f.Key,SegmentKey:r.SegmentKey,Rank:int32(r.Rank)})
   if err!=nil{return fmt.Errorf("importing rule for flag %q: %w",f.Key,err)}
   for _,d:=range r.Distributions {
    variant,found:=variants[f.Key+":"+d.VariantKey]
    if !found {return fmt.Errorf("finding variant %q for flag %q",d.VariantKey,f.Key)}
    if _,err:=i.store.CreateDistribution(ctx,&flipt.CreateDistributionRequest{FlagKey:f.Key,RuleId:rule.Id,VariantId:variant.Id,Rollout:d.Rollout});err!=nil{return fmt.Errorf("importing distribution for flag %q: %w",f.Key,err)}
   }
  }
 }
 return nil
}
